// research: 'strong momentum' for a push has no bar-level definition given
firstPushStrong = pushMomentumScore(push1) >= strongMomentumThreshold;
secondPushStrong = pushMomentumScore(push2) >= strongMomentumThreshold;
skipHigh2Entry = firstPushStrong && secondPushStrong;
waitForBreakoutPullback = skipHigh2Entry;

patternBrokeDownBar = (isDoubleTop[k] || isHeadAndShouldersTop[k]) && close[k] < breakoutLevel[k]; // the neckline or dip low broke on some recent bar k
failedToFollowThrough = barsSinceBreakout <= maxFollowThroughBars && close[0] > breakoutLevel;
// enter with the larger (bull) trend once the failed breakout closes back above the level
isFailedBreakoutSignal = failedToFollowThrough && close[0] > open[0];
enterLongNextBarOpen = isFailedBreakoutSignal;

spikeBrokeRangeHigh = high[k] > rangeHigh; // some recent bar k spiked above the range top
failedAndReversed = barsSinceSpike <= maxReversalBars && close[0] < rangeHigh && close[0] < open[0];
enterShortNextBarOpen = isTradingRange[0] && spikeBrokeRangeHigh && failedAndReversed;

nearBottom = close[0] <= rangeLow + nearExtremeAtr * atr(atrLookback);
limitPrice = priorSwingLow - spikeLimitOffsetTicks * tickSize;
enterLongLimit = isBearSpike[0] && nearBottom && low[0] <= limitPrice;

isStrongBullTrendBar = close[0] > open[0] && (close[0] - open[0]) >= strongBodyFraction * (high[0] - low[0]);
limitPrice = close[0];
enterLongOnLimitNextBar = isStrongBullTrendBar && isStrongBullSpike[0] && low[1] <= limitPrice;

isStrongBullTrendBar0 = close[0] > open[0] && (close[0] - open[0]) >= strongBodyFraction * (high[0] - low[0]);
isStrongBullTrendBar1 = close[1] > open[1] && (close[1] - open[1]) >= strongBodyFraction * (high[1] - low[1]);
limitPrice = low[0];
enterLongOnLimitNextBar = isOpeningRangeStillForming[0] && isStrongBullTrendBar0 && isStrongBullTrendBar1 && low[1] <= limitPrice;

isBearCloseBar = close[0] < open[0];
closeInTopHalfOfPriorBar = (close[0] - low[1]) / (high[1] - low[1] + epsilon) > 0.5;
enterShortAtClose = isTradingRangeDay[0] && isBullSpike[0] && isNearTopOfRange[0] && isBearCloseBar
   && closeInTopHalfOfPriorBar && isSecondReversalAttempt[0];

// research: adding independently-tracked with-trend units on every qualifying bar is a multi-unit position feature the engine does not model
isStrongBullTrendBar0 = close[0] > open[0] && (close[0]-open[0]) >= strongBodyFraction*(high[0]-low[0]);
